      key: "2026-09-03",
      startDay: "2026-09-03",
      endDay: "2026-09-03",
      force: true,
    };
    // 全部（空数组）：两目录都在
    const cfgForSnap = normalizeReportConfig({ push: { enabled: false }, directories: [] });
