            },
          },
          effect: (fn: () => unknown) => {
            const disposer = fn();
            settingsEvents.push("effect-registered");
            return typeof disposer === "function" ? disposer : () => {};
          },
          on: (event: string, _cb: (...args: unknown[]) => void) => {
