  it("report 月报提示词页带弱模型 footnote", () => {
    expect(reportSource.includes("reportWeakModelNote")).toBe(true);
  });

  it("report 幂等复用 footnote 保留（PM3）", () => {
    expect(reportSource.includes("reportGenIdempotentHint")).toBe(true);
  });
});

